-- Spanish quest text this database never had, mostly the spoken parts: 10194
-- hand-in texts and 4463 "you are still missing" texts had no Spanish, against
-- Russian's 12986. The quest log itself was already nearly complete.
--
-- Sources are a 3.3.5 database and a retail one. Neither can be imported on id
-- alone - Cataclysm rewrote much of the 1-60 content and reused the quest ids -
-- so every row is gated on the English text matching what this database has.
-- The gate is applied after normalising whitespace and $B tokens, which is not
-- cosmetic: raw, only 331 rows passed; normalised, 741 do.
--
-- Also repairs 30 rows imported with locale 'frFr'. GetLocaleByName compares
-- case-sensitively, so those French translations were being dropped in silence.

UPDATE `quest_offer_reward_locale` SET `locale` = 'frFR' WHERE BINARY `locale` = 'frFr';


-- ---------------------------------------------------------------------
-- 1) OfferRewardText - the hand-in dialogue.
-- ---------------------------------------------------------------------

-- ---------------------------------------------------------------------
-- 2) RequestItemsText - the "you are still missing" window.
-- ---------------------------------------------------------------------

-- ---------------------------------------------------------------------
-- 3) Quest log text.
--
-- Each of the four columns carries its own English gate, so a row can bring a
-- verified Title while leaving Details empty. ON DUPLICATE KEY UPDATE only ever
-- writes over a column that is empty, and the NULLIF guards stop an empty
-- imported value from blanking one that is already there.
-- ---------------------------------------------------------------------
ON DUPLICATE KEY UPDATE
    `Title`         = COALESCE(NULLIF(`Title`,''),         NULLIF(VALUES(`Title`),''),         ''),
    `Details`       = COALESCE(NULLIF(`Details`,''),       NULLIF(VALUES(`Details`),''),       ''),
    `Objectives`    = COALESCE(NULLIF(`Objectives`,''),    NULLIF(VALUES(`Objectives`),''),    ''),
    `CompletedText` = COALESCE(NULLIF(`CompletedText`,''), NULLIF(VALUES(`CompletedText`),''), '');
