(11609,'esES','¿Has recuperado un conjunto completo de objetos rituales?'),
(11610,'esES','¿Has completado las ceremonias de los ancestros?'),
(11612,'esES','¿Has liberado la Cantera Fríoescollo de nuestros enemigos?'),
(11613,'esES','¿Lo conseguiste, $r? Los Kvaldir son guerreros muy crueles. No esperes ninguna tregua de ellos.'),
